// ../plugin/src/hooks/magic-context/m0-token-breakdown.ts
function computeM0BlockTokens(db, sessionId, args) {
  const {
    m0Text,
    m1Text,
    projectIdentity,
    injectionBudgetTokens,
    memoryBlockCount,
    compartmentTokensOverride
  } = args;
  const docsBlock = extractM0Block(m0Text, "project-docs");
  const docsTokens = docsBlock ? estimateTokens(docsBlock) : 0;
  const profileBlock = extractM0Block(m0Text, "user-profile");
  const profileTokens = profileBlock ? estimateTokens(profileBlock) : 0;
  let memoryTokens = 0;
  let memoryFromM0 = false;
  const memoryBlock = extractM0Block(m0Text, "project-memory");
  if (memoryBlock) {
    memoryTokens = estimateTokens(memoryBlock);
    memoryFromM0 = true;
  }
  const muralTokens = m0Text.includes("<memory-mural>") ? 1521 : 0;
  let compartmentTokens = 0;
  const historyBlock = extractM0Block(m0Text, "session-history");
  if (typeof compartmentTokensOverride === "number" && Number.isFinite(compartmentTokensOverride) && compartmentTokensOverride >= 0) {
    compartmentTokens = compartmentTokensOverride;
  } else if (historyBlock) {
    compartmentTokens = estimateTokens(historyBlock);
    const newCompartmentsBlock = m1Text ? extractM0Block(m1Text, "new-compartments") : null;
    if (newCompartmentsBlock)
      compartmentTokens += estimateTokens(newCompartmentsBlock);
  } else {
    try {
      const compRows = db.prepare("SELECT content, title, start_message, end_message FROM compartments WHERE session_id = ?").all(sessionId);
      for (const c of compRows) {
        compartmentTokens += estimateTokens(`## ${c.start_message}-${c.end_message} · ${c.title}
${c.content}
`);
      }
    } catch {}
  }
  if (!memoryFromM0 && memoryBlockCount > 0 && projectIdentity) {
    try {
      const memories = getMemoriesByProject(db, projectIdentity, ["active", "permanent"]);
      const selected = injectionBudgetTokens ? trimMemoriesToBudgetV2(sessionId, memories, injectionBudgetTokens).renderOrder : memories;
      const block = renderMemoryBlockV2(selected);
      memoryTokens = block ? estimateTokens(block) : 0;
    } catch {
      memoryTokens = 0;
    }
  }
  return {
    docsTokens,
    profileTokens,
    memoryTokens,
    muralTokens,
    compartmentTokens,
    factTokens: 0
  };
}

// ../plugin/src/shared/cache-ttl-display.ts
